import { priceFor } from '/search.js';

const $ = (s) => document.querySelector(s);

// Everything rendered below comes from somewhere untrusted: ship names, itinerary
// titles and port names are scraped off a third-party site, and the filter is
// generated by a language model. Build DOM nodes and set textContent rather than
// interpolating into innerHTML — an apostrophe in a port name would be a bug, and
// a crafted string would be an XSS hole.
const el = (tag, props = {}, ...kids) => {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(props)) {
    if (v == null) continue;
    if (k === 'class') n.className = v;
    else if (k === 'text') n.textContent = v;
    else n.setAttribute(k, v);
  }
  for (const kid of kids.flat()) if (kid != null) n.append(kid);
  return n;
};

/** Only http(s) may reach an href or src — blocks javascript: and data: URLs. */
const safeUrl = (u) => (typeof u === 'string' && /^https?:\/\//i.test(u) ? u : null);
const state = { all: [], subset: null, message: null, values: {}, facets: {}, searchCabin: null,
  selections: {}, selectionsOk: true, selectionsWhy: null };

const EXAMPLES = [
  'a 4-night Bahamas cruise with a balcony under $700',
  'something cheap out of Fort Lauderdale',
  'a week in the Caribbean on the Icon of the Seas',
  'an adults-only ship with a Michelin restaurant',
];

const money = (n) => '$' + n.toLocaleString('en-US', { maximumFractionDigits: 0 });
const prettyDate = (iso) =>
  new Date(iso + 'T00:00:00').toLocaleDateString('en-US',
    { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
const titleCase = (s) => String(s).split('-').map(w => w[0].toUpperCase() + w.slice(1)).join(' ');

const CABIN_NAMES = { interior: 'Interior', oceanview: 'Ocean view', balcony: 'Balcony', suite: 'Suite' };
const cabinName = (c) => CABIN_NAMES[c] ?? titleCase(c ?? 'cabin');

/** The dropdown wins over the search: it is the more recent, more specific choice. */
const chosenCabin = () => state.facets.cabin || state.searchCabin || null;

/** The price a card shows and the slider and sort use — the shared rule. */
const shownPrice = (s) => priceFor(s, chosenCabin()) ?? priceFor(s, null);

const HOME_KEY = 'ai-cruises.home';
const readHome = () => { try { return localStorage.getItem(HOME_KEY) || 'YYZ'; } catch { return 'YYZ'; } };
const saveHome = (code) => { try { localStorage.setItem(HOME_KEY, code); } catch { /* private mode: not remembered */ } };
const shortDate = (iso) => new Date(iso + 'T00:00:00').toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
const hm = (min) => `${Math.floor(min / 60)}h ${String(min % 60).padStart(2, '0')}m`;
const checkedAgo = (iso) => {
  const days = Math.floor((Date.now() - Date.parse(iso)) / 86_400_000);
  return days <= 0 ? 'checked today' : `checked ${days} day${days === 1 ? '' : 's'} ago`;
};

let panelSailing = null;
/** The ✈ button that opened the panel; focus goes back to it on close. */
let panelOpener = null;
/** Bumped per search, so a slower, older search never overwrites a newer one's answer. */
let flightsRequest = 0;

/** Marks a block to rise in as the `i`th in line. */
const rise = (node, i) => { node.classList.add('rise'); node.style.setProperty('--i', i); return node; };

function closePanel() {
  // Slides out; the CSS hides it once the slide has finished. Content stays until then.
  $('#panel').classList.remove('open');
  $('#panel-backdrop').classList.remove('open');
  panelSailing = null;
  panelOpener?.focus({ preventScroll: true });
  panelOpener = null;
}

function openPanel(s, opener) {
  recordView(s);
  panelSailing = s;
  panelOpener = opener ?? null;
  const panel = $('#panel');
  panel.textContent = '';
  panel.scrollTop = 0;

  const close = el('button', { class: 'close', type: 'button', 'aria-label': 'Close', text: '✕' });
  close.onclick = closePanel;
  const src = safeUrl(s.image);
  const photo = src ? el('img', { src, alt: '' }) : null;
  // A photo that fails to load leaves the plain gradient, not a broken-image icon.
  if (photo) photo.onerror = () => photo.remove();
  const hero = el('div', { class: 'hero' },
    photo,
    close,
    el('div', { class: 'hero-text' },
      el('div', { class: 'eyebrow', text: '✈ Getting there' }),
      el('h2', { id: 'panel-title', text: s.itinerary ?? titleCase(s.destination ?? 'Cruise') }),
      el('div', { class: 'hero-meta', text: `${s.ship} · ${prettyDate(s.departureDate)} · ${s.nights} nights` }),
      starsFor(s)));

  const home = el('input', { value: readHome(), maxlength: '3', 'aria-label': 'Home airport code' });
  const flights = el('div', { class: 'flights', 'aria-live': 'polite' });
  panel.append(hero, el('div', { class: 'panel-body' },
    rise(el('label', { class: 'home' }, 'Flying from', home), 0),
    flights));
  panel.setAttribute('aria-labelledby', 'panel-title');

  home.onchange = () => {
    const code = home.value.trim().toUpperCase();
    home.value = code;
    if (!/^[A-Z]{3}$/.test(code)) {
      flights.textContent = '';
      flights.append(el('div', { class: 'message', text: 'Use a three-letter airport code, like YYZ.' }));
      return;
    }
    saveHome(code);
    showFlights(s, code, flights);
  };

  panel.classList.add('open');
  $('#panel-backdrop').classList.add('open');
  close.focus({ preventScroll: true });
  showFlights(s, home.value, flights);
}

/** A shimmering outline of the answer, while the search runs. */
function searching(body) {
  body.textContent = '';
  body.append(
    el('div', { class: 'note', text: 'Searching flights… (about 10 seconds)' }),
    el('div', { class: 'sk sk-leg' }), el('div', { class: 'sk sk-fare' }),
    el('div', {}, el('div', { class: 'sk sk-row' }), el('div', { class: 'sk sk-row', style: 'margin-top:8px' })));
}

/** One flight: "Flying out · Fri, May 7" over YYZ Toronto - - ✈ - - YVR Vancouver. */
function legCard(leg, label, names) {
  const stop = (code, end) => el('div', { class: end ? 'stop end' : 'stop' },
    el('b', { text: code }), el('span', { text: names?.[code] ?? '' }));
  return el('div', { class: 'leg', 'aria-label': `${label}: ${names?.[leg.from] ?? leg.from} (${leg.from}) to ${names?.[leg.to] ?? leg.to} (${leg.to}), ${shortDate(leg.date)}` },
    el('div', { class: 'leg-label', text: `${label} · ${shortDate(leg.date)}` }),
    el('div', { class: 'leg-route' },
      stop(leg.from, false),
      el('div', { class: 'path', 'aria-hidden': 'true' }, el('span', { text: '✈' })),
      stop(leg.to, true)));
}

async function showFlights(s, home, body) {
  const mine = ++flightsRequest;
  searching(body);
  let data;
  try {
    const res = await fetch(`/api/flights?id=${encodeURIComponent(s.id)}&home=${encodeURIComponent(home)}`);
    data = await res.json();
  } catch {
    data = { message: "Couldn't reach the flight search" };
  }
  // Closed, another cruise opened, or a newer search (e.g. a changed home airport) started.
  if (panelSailing !== s || mine !== flightsRequest) return;
  body.textContent = '';
  let i = 1;

  const { outbound, inbound } = data.route ?? {};
  if (outbound || inbound) {
    body.append(rise(el('div', { class: 'legs' },
      outbound ? legCard(outbound, 'Flying out', data.names) : null,
      inbound ? legCard(inbound, 'Flying home', data.names) : null), i++));
  }

  const link = safeUrl(data.googleFlightsUrl);
  const googleLink = link ? el('a', { class: 'gflights', href: link, target: '_blank', rel: 'noopener', text: 'See all on Google Flights ↗' }) : null;

  if (data.fromPrice == null) {
    body.append(rise(el('div', { class: 'message', text: data.message ?? 'No flights found.' }), i++));
    if (googleLink) body.append(rise(el('div', { class: 'panel-foot' }, googleLink), i++));
    return;
  }

  const shown = shownPrice(s);
  const cruisePrice = shown.notListed ? s.price : shown.price;
  const what = outbound && inbound ? 'flights' : (outbound ? 'flight out' : 'flight home');
  body.append(rise(el('div', { class: 'fare' },
    el('div', { class: 'fare-label', text: `${outbound && inbound ? 'Flights' : 'Flight'} from ${home}, from about` }),
    el('div', { class: 'fare-amount' }, money(data.fromPrice), el('small', { text: ' per person' })),
    el('div', { class: 'fare-total' }, `Cruise + ${what} from about `, el('b', { text: money(cruisePrice + data.fromPrice) })),
    shown.notListed
      ? el('div', { class: 'fare-note', text: `Cruise at its cheapest, ${cabinName(s.cabin).toLowerCase()} — the ${cabinName(shown.cabin).toLowerCase()} price isn't listed.` })
      : null), i++));

  if (data.options.length > 0) {
    body.append(rise(el('div', {},
      el('div', { class: 'options-head', text: 'Cheapest options' }),
      el('div', { class: 'options', style: 'margin-top:8px' },
        data.options.map((o, n) => el('div', { class: n === 0 ? 'option best' : 'option' },
          el('span', { class: 'o-price', text: money(o.price) }),
          el('span', { class: 'o-air', text: o.airlines }),
          el('span', { class: 'o-when', text: `${o.departs.slice(11)} · ${hm(o.minutes)}` }),
          el('span', { class: 'o-stops', text: o.stops === 0 ? 'nonstop' : `${o.stops} stop${o.stops === 1 ? '' : 's'}` }))))), i++));
  }

  body.append(rise(el('div', { class: 'note' },
    'Prices are for the whole trip, per person; times are for the flight out.',
    data.note ? el('div', { text: data.note }) : null), i++));
  body.append(rise(el('div', { class: 'panel-foot' },
    googleLink, el('span', { class: 'note', text: checkedAgo(data.fetchedAt) })), i++));
}

$('#panel-backdrop').onclick = closePanel;
document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && panelSailing) closePanel(); });

async function boot() {
  const res = await fetch('/api/dataset');
  const data = await res.json();
  if (!res.ok) { $('#sub').textContent = data.error; return; }

  state.all = data.sailings;
  state.values = data.values;
  // Ratings load once; each change updates them in place. Unavailable is not an error page:
  // search works, and one notice says why (see buildYearChips).
  try {
    const sres = await fetch('/api/selections');
    const sdata = await sres.json();
    if (!sres.ok) throw new Error(sdata.error);
    state.selections = Object.fromEntries(sdata.selections.map((r) => [r.sailingId, r]));
  } catch (err) {
    state.selectionsOk = false;
    state.selectionsWhy = `Ratings are unavailable: ${err.message}`;
  }
  $('#sub').textContent =
    `${data.sailings.length} sailings · ${data.values.line.length} line(s) · ` +
    `scraped ${new Date(data.scrapedAt).toLocaleString()}`;

  $('#examples').innerHTML = '';
  for (const ex of EXAMPLES) {
    const b = document.createElement('button');
    b.type = 'button'; b.textContent = ex;
    b.onclick = () => { $('#q').value = ex; $('#form').requestSubmit(); };
    $('#examples').append(b);
  }

  buildYearChips();
  buildFacets();
  render();
}

/**
 * Year chips, derived from the data — never a hardcoded list.
 *
 * The same voyage repeats weekly across a ~20-month window, so a year is the
 * natural first cut: it turns 320 near-identical rows into "which season am I
 * shopping for". Defaults to the current year, falling back to the earliest year
 * with sailings — otherwise running this in a year the dataset does not cover
 * would open on an empty page.
 */
function buildYearChips() {
  const counts = new Map();
  for (const s of state.all) {
    const y = s.departureDate.slice(0, 4);
    counts.set(y, (counts.get(y) ?? 0) + 1);
  }
  const years = [...counts.keys()].sort();
  if (years.length === 0) return;

  const thisYear = String(new Date().getFullYear());
  state.facets.year = counts.has(thisYear) ? thisYear : years[0];

  const host = el('div', { class: 'years' });
  const chips = [];

  const chip = (value, label, count) => {
    const b = el('button', { type: 'button', class: 'yearchip', text: `${label} ` });
    b.append(el('span', { class: 'yearcount', text: String(count) }));
    b.onclick = () => {
      state.facets.year = value;
      syncYearChips();
      render();
    };
    chips.push({ el: b, value });
    host.append(b);
    return b;
  };

  if (state.selectionsOk) {
    const mine = chip('mine', 'My cruises', Object.keys(state.selections).length);
    updateMineCount = () => {
      mine.querySelector('.yearcount').textContent = String(Object.keys(state.selections).length);
    };
    host.append(el('span', { class: 'chip-divider', 'aria-hidden': 'true' }));
  }
  chip(null, 'All', state.all.length);
  for (const y of years) chip(y, y, counts.get(y));

  syncYearChips = () => {
    for (const c of chips) c.el.classList.toggle('on', c.value === state.facets.year);
    // Until a sort is chosen, the box names the order shown: My cruises keeps its own
    // (rated first), so "Cheapest first" would be wrong there — and picking it, already
    // selected, would fire no change. Review finding.
    const sort = $('#f-sort');
    if (sort && !state.facets.sort) sort.value = state.facets.year === 'mine' ? 'mine' : 'price';
  };
  syncYearChips();

  $('#years').replaceChildren(host);
}

let syncYearChips = () => {};

/**
 * Everything viewed or rated: rated first, highest first; then by most recent view. A
 * sailing no longer listed (departed, or gone from the scrape) comes from its snapshot.
 */
function mineList() {
  const byId = new Map(state.all.map((s) => [s.id, s]));
  return Object.values(state.selections)
    .sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0)
      || String(b.lastViewed ?? '').localeCompare(String(a.lastViewed ?? '')))
    .map((r) => byId.get(r.sailingId) ?? { ...r.snapshot, id: r.sailingId, unlisted: true });
}

function buildFacets() {
  const v = state.values;
  const maxPrice = Math.ceil(Math.max(...state.all.map(s => s.price)) / 50) * 50;
  const defs = [
    ['destination', 'Destination', v.destination.map(d => [d, titleCase(d)])],
    ['cabin', 'Cabin', v.cabin.map(c => [c, titleCase(c)])],
    ['tripType', 'Trip type', (v.tripType ?? []).map(t => [t, t === 'cruisetour' ? 'Cruisetour (with land days)' : 'Cruise'])],
    ['departurePort', 'Leaves from', v.departurePort.map(p => [p, p])],
    ['nights', 'Nights', v.nights.map(n => [String(n), n + ' nights'])],
    ['ship', 'Ship', [...new Set(state.all.map(s => s.ship))].sort().map(s => [s, s])],
  ];

  const host = $('#facets');
  host.innerHTML = '';
  for (const [key, label, opts] of defs) {
    const wrap = document.createElement('div');
    wrap.className = 'facet';
    wrap.innerHTML = `<label for="f-${key}">${label}</label>`;
    const sel = document.createElement('select');
    sel.id = 'f-' + key;
    sel.append(el('option', { value: '', text: 'Any' }));
    for (const [val, text] of opts) sel.append(el('option', { value: val, text }));
    sel.onchange = () => { state.facets[key] = sel.value || null; render(); };
    wrap.append(sel);
    host.append(wrap);
  }

  const priceWrap = document.createElement('div');
  priceWrap.className = 'facet';
  priceWrap.innerHTML = `<label for="f-price">Max price <span id="priceOut">${money(maxPrice)}</span></label>`;
  const range = document.createElement('input');
  range.type = 'range'; range.id = 'f-price';
  range.min = 0; range.max = maxPrice; range.step = 25; range.value = maxPrice;
  range.oninput = () => {
    $('#priceOut').textContent = money(+range.value);
    state.facets.maxPrice = +range.value >= maxPrice ? null : +range.value;
    render();
  };
  priceWrap.append(range);
  host.append(priceWrap);

  const sortWrap = document.createElement('div');
  sortWrap.className = 'facet';
  sortWrap.innerHTML = `<label for="f-sort">Sort</label>`;
  const sort = document.createElement('select');
  sort.id = 'f-sort';
  sort.innerHTML = `<option value="mine" hidden>Rated first</option>
                    <option value="price" selected>Cheapest first</option>
                    <option value="date">Soonest first</option>
                    <option value="nights">Longest first</option>`;
  sort.onchange = () => { state.facets.sort = sort.value; render(); };
  sortWrap.append(sort);
  host.append(sortWrap);
}

function applyFacets(list) {
  const f = state.facets;
  let out = list.filter(s =>
    (!f.destination || s.destination === f.destination) &&
    (!f.cabin || priceFor(s, f.cabin) !== null) &&
    (!f.tripType || (s.tripType === undefined ? 'cruise' : s.tripType) === f.tripType) &&
    (!f.departurePort || s.departurePort === f.departurePort) &&
    (!f.nights || s.nights === +f.nights) &&
    (!f.ship || s.ship === f.ship) &&
    (!f.year || f.year === 'mine' || s.departureDate.startsWith(f.year)) &&
    // A not-listed cabin costs at least the cheapest one, so that is its floor.
    (f.maxPrice == null || (shownPrice(s).notListed ? s.price : shownPrice(s).price) <= f.maxPrice));

  const by = f.sort ?? (f.year === 'mine' ? null : 'price');
  if (!by) return out;
  out = [...out].sort((a, b) =>
    by === 'date' ? a.departureDate.localeCompare(b.departureDate)
    : by === 'nights' ? b.nights - a.nights
    // Not-listed prices sort last: unknown, so they cannot be "cheapest first".
    : (shownPrice(a).price ?? Infinity) - (shownPrice(b).price ?? Infinity));
  return out;
}

function flightsButton(s) {
  const b = el('button', { class: 'flights-btn', type: 'button', text: '✈ Flights' });
  b.onclick = () => openPanel(s, b);
  return b;
}

/** Called when the My cruises count changes; buildYearChips replaces it. */
let updateMineCount = () => {};
/** Bumped per rating click, per sailing, so a slow earlier answer never repaints over a later one. */
const rateTickets = {};
// Each cruise's rating saves go one after another, so the server ends on the last click:
// sent side by side, 3 then 5 could arrive as 5 then 3.
const rateChains = {};

/** Five buttons; clicking the current rating clears it. One group per copy of the cruise on screen. */
function starsFor(s) {
  if (!state.selectionsOk) return null;
  const group = el('div', { class: 'stars', role: 'group', 'aria-label': 'Your rating', 'data-stars': s.id });
  for (let n = 1; n <= 5; n += 1) {
    const b = el('button', { type: 'button', 'aria-label': `Rate ${n} star${n === 1 ? '' : 's'}` });
    b.onclick = (e) => {
      e.stopPropagation();
      rate(s, (state.selections[s.id]?.rating ?? 0) === n ? null : n);
    };
    group.append(b);
  }
  paintGroup(group, state.selections[s.id]?.rating ?? 0);
  return group;
}

function paintGroup(group, rating) {
  [...group.children].forEach((b, i) => {
    b.className = i < rating ? 'star on' : 'star';
    b.textContent = i < rating ? '★' : '☆';
    b.setAttribute('aria-pressed', String(i + 1 === rating));
  });
}

function paintStars(id) {
  const rating = state.selections[id]?.rating ?? 0;
  for (const g of document.querySelectorAll(`[data-stars="${CSS.escape(id)}"]`)) paintGroup(g, rating);
}

async function rate(s, rating) {
  const ticket = (rateTickets[s.id] = (rateTickets[s.id] ?? 0) + 1);
  const before = state.selections[s.id];
  state.selections[s.id] = { ...(before ?? { sailingId: s.id, views: 0, snapshot: s }), rating };
  paintStars(s.id);
  try {
    const send = (rateChains[s.id] ?? Promise.resolve()).then(() => fetch('/api/selections/rating', {
      method: 'PUT', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ id: s.id, rating }),
    }));
    rateChains[s.id] = send.catch(() => {});
    const res = await send;
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    if (ticket !== rateTickets[s.id]) return; // a later click owns the display now
    if (data.selection) state.selections[s.id] = data.selection;
    else delete state.selections[s.id];
  } catch (err) {
    if (ticket !== rateTickets[s.id]) return;
    if (before) state.selections[s.id] = before;
    else delete state.selections[s.id];
    console.error('Rating not saved:', err.message);
  }
  paintStars(s.id);
  updateMineCount();
}

/** In the background: the link and the panel never wait for it. Unlisted cruises can't be viewed. */
function recordView(s) {
  if (!state.selectionsOk || s.unlisted) return;
  fetch('/api/selections/view', {
    method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ id: s.id }), keepalive: true,
  })
    .then((res) => (res.ok ? res.json() : null))
    .then((data) => {
      if (!data?.selection) return;
      state.selections[s.id] = data.selection;
      markViewed(s);
      updateMineCount();
    })
    .catch(() => {});
}

function viewedTag(s) {
  const r = state.selections[s.id];
  if (!r?.views) return null;
  const last = r.lastViewed ? new Date(r.lastViewed).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : '';
  // A button: clicking it undoes the views, for an accidental View ↗.
  const b = el('button', {
    type: 'button', class: 'viewed', text: 'Viewed ✕',
    title: `Viewed ${r.views}× · last ${last} — click to mark as not viewed`,
    'aria-label': 'Viewed — mark as not viewed',
  });
  b.onclick = (e) => { e.stopPropagation(); unview(s); };
  return b;
}

/** Undoes the views. A rated cruise stays in My cruises, unviewed; an unrated one leaves it. */
async function unview(s) {
  try {
    const res = await fetch('/api/selections/unview', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ id: s.id }),
    });
    const data = await res.json();
    if (!res.ok) throw new Error(data.error);
    if (data.selection) state.selections[s.id] = data.selection;
    else delete state.selections[s.id];
  } catch (err) {
    console.error('View not undone:', err.message);
    return;
  }
  markViewed(s);
  updateMineCount();
  // On My cruises, a cruise that has just left it goes from the list too.
  if (state.facets.year === 'mine' && !state.selections[s.id]) render();
}

function markViewed(s) {
  for (const t of document.querySelectorAll(`[data-thumb="${CSS.escape(s.id)}"]`)) {
    t.querySelector('.viewed')?.remove();
    const tag = viewedTag(s);
    if (tag) t.append(tag);
  }
}

function render() {
  const mine = state.facets.year === 'mine';
  const base = mine ? mineList() : (state.subset ?? state.all);
  const list = applyFacets(base);
  const countEl = $('#count');
  if (countEl) {
    countEl.textContent = `${list.length} of ${base.length} shown`;
  }
  // The table is My cruises in another form, so its link shows with that list. Without
  // ratings there is no My cruises chip, and the reason shows here instead.
  $('#results-note').replaceChildren(...(mine
    ? ['My cruises · ', el('a', { class: 'table-link', href: '/mine', text: 'Table view ↗' })]
    : state.selectionsOk ? [] : [state.selectionsWhy ?? '']));

  const host = $('#results');
  host.textContent = '';

  if (list.length === 0) {
    const why = mine
      ? "Nothing here yet — open a cruise's View ↗ or ✈ Flights, or give it stars."
      : (state.message ?? "Nothing matches those filters — you've had enough sun anyway.");
    const box = el('div', { class: 'empty', text: why });
    box.style.gridColumn = '1/-1';
    host.append(box);
    $('#more').hidden = true;
    return;
  }

  renderList = list;
  built = 0;
  appendCards(BATCH);
}

/**
 * Cards are built in batches as you scroll: building all 1,857 took ~0.6 s on a desktop
 * and ~2 s on a slowed phone, on every filter or sort change (measured 2026-10-14).
 */
const BATCH = 60;
let renderList = [];
let built = 0;

function appendCards(count) {
  const next = renderList.slice(built, built + count);
  $('#results').append(...next.map(cardFor));
  built += next.length;
  const more = $('#more');
  more.hidden = built >= renderList.length;
  $('#more-count').textContent = `Showing ${built.toLocaleString('en-US')} of ${renderList.length.toLocaleString('en-US')}`;
}

// The "Showing N of M" line doubles as the marker: within about two screens of it, the
// next batch is built. Re-observing makes it fire again if it is still in range afterwards.
const moreObserver = new IntersectionObserver((entries) => {
  if (!entries.some((e) => e.isIntersecting) || $('#more').hidden) return;
  appendCards(BATCH);
  moreObserver.unobserve($('#more'));
  moreObserver.observe($('#more'));
}, { rootMargin: '0px 0px 1600px 0px' });
moreObserver.observe($('#more'));
$('#show-all').onclick = () => appendCards(Infinity);

function cardFor(s) {
  const thumb = el('div', { class: 'thumb', 'data-thumb': s.id });
  const img = safeUrl(s.image);
  const noPhoto = () => el('span', { class: 'no-photo', text: 'Image not available' });
  if (img) {
    const photo = el('img', { loading: 'lazy', alt: '', src: img });
    // A photo that fails to load says so too, rather than leaving a broken-image icon.
    photo.onerror = () => photo.replaceWith(noPhoto());
    thumb.append(photo);
  } else {
    thumb.append(noPhoto());
  }
  thumb.append(el('span', { class: 'nights', text: `${s.nights} nights` }));
  const tag = viewedTag(s);
  if (tag) thumb.append(tag);
  if (s.unlisted) thumb.append(el('span', { class: 'gone', text: 'No longer listed' }));
  if (s.tripType === 'cruisetour') {
    thumb.append(el('span', { class: 'tour', text: 'Cruisetour · includes land days' }));
  }

  const shown = shownPrice(s);
  const price = shown.notListed
    ? el('div', { class: 'cabin', text: `${cabinName(shown.cabin)} price not listed · from ${money(s.price)} ${cabinName(s.cabin).toLowerCase()}` })
    : el('div', { class: 'price', text: money(shown.price) }, el('small', { text: ' pp' }));
  const priceLabel = shown.notListed ? null : el('div', { class: 'cabin', text: cabinName(shown.cabin) });

  // Every cabin's price, cheapest type first — useful whatever was searched for.
  const table = s.cabinPrices ? Object.keys(CABIN_NAMES).filter((c) => s.cabinPrices[c] !== undefined) : [];
  const cabinRow = table.length > 1
    ? el('div', { class: 'ports cabins', text: table.map((c) => `${cabinName(c)} ${money(s.cabinPrices[c])}`).join(' · ') })
    : null;

  const link = safeUrl(s.url);
  const view = link ? el('a', { class: 'book', href: link, target: '_blank', rel: 'noopener', text: ' View ↗' }) : null;
  if (view) {
    view.onclick = () => recordView(s); // also ⌘- and ctrl-click, which are still clicks
    // A middle-click opens a new tab without a click event. (Right-click → Open in New Tab
    // can't be seen by the page at all.)
    view.onauxclick = (e) => { if (e.button === 1) recordView(s); };
  }
  const foot = el('div', { class: 'foot' },
    el('div', {}, price, priceLabel),
    el('div', {}, s.unlisted ? null : flightsButton(s), view));

  return el('article', { class: s.unlisted ? 'card unlisted' : 'card' }, thumb,
    el('div', { class: 'body' },
      el('div', { class: 'title', text: s.itinerary ?? titleCase(s.destination ?? 'Cruise') }),
      el('div', { class: 'meta', text: `${s.ship} · ${s.line}` }),
      el('div', { class: 'meta', text: `${prettyDate(s.departureDate)} · from ${s.departurePort}` }),
      s.ports?.length ? el('div', { class: 'ports', text: `Calls at ${s.ports.join(' · ')}` }) : null,
      cabinRow,
      foot,
      starsFor(s)));
}

$('#form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const q = $('#q').value.trim();
  if (!q) return;

  $('#go').disabled = true;
  $('#go').textContent = 'Thinking…';
  const box = $('#understood');
  box.hidden = false;
  box.textContent = '';
  box.append(el('h2', { text: 'Working' }),
             el('p', { text: 'Asking the model to turn that into a filter…' }));

  try {
    const res = await fetch('/api/search', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ q }),
    });
    const data = await res.json();

    if (!res.ok) {
      box.textContent = '';
      box.append(el('h2', { text: 'Problem' }), el('p', { text: data.error }));
      if (data.raw) box.append(el('pre', { text: data.raw }));
      return;
    }

    const unrec = (data.filter.unrecognised ?? []).filter(Boolean);
    box.textContent = '';
    box.append(el('h2', { text: 'Understood as' }));

    if (unrec.length) {
      const warn = el('div', { class: 'warn' }, 'Nothing in these listings describes ');
      unrec.forEach((u, i) => {
        if (i) warn.append(', ');
        warn.append(el('strong', { text: `\u201C${u}\u201D` }));
      });
      warn.append(' — I ignored that part.');
      box.append(warn);
    }

    const n = data.results.length;
    const line = el('p', {}, `${data.understood || 'no constraints'} — `,
      el('strong', { text: String(n) }),
      ` match${n === 1 ? '' : 'es'}, in ${data.tookMs} ms.`);
    box.append(line);

    // Shown, not enforced: prices span currencies and the filter compares them
    // as-is. Worth saying, not worth withholding the results over.
    if (data.notice) box.append(el('div', { class: 'warn', text: data.notice }));

    // The plain-English line above is for everyone; the raw filter is the developer's view.
    box.append(el('details', { class: 'filter-json' },
      el('summary', { text: 'Show the filter' }),
      el('pre', { text: JSON.stringify(data.filter, null, 2) })));

    // A year chip and a dated search are two answers to the same question. If the
    // request named dates ("in 2027", "next spring"), that is the more specific
    // intent — clear the chip rather than silently intersecting them to zero.
    if (data.filter.dateFrom || data.filter.dateTo) {
      state.facets.year = null;
      syncYearChips();
    }
    // Results replace the view, so a search run from My cruises shows what it found
    // (the chip would otherwise keep showing My cruises over them). Review finding.
    if (state.facets.year === 'mine') {
      state.facets.year = null;
      syncYearChips();
    }

    state.subset = data.results;
    state.searchCabin = data.filter.cabin ?? null;
    state.message = data.message;
    render();
  } catch (err) {
    box.textContent = '';
    box.append(el('h2', { text: 'Problem' }), el('p', { text: err.message }));
  } finally {
    $('#go').disabled = false;
    $('#go').textContent = 'Search';
  }
});

boot();
